function isBirthdayThisWeek(aniv) {
  if (!aniv) return false;
  const now = new Date();
  const start = new Date(now); start.setDate(now.getDate() - ((now.getDay() + 6) % 7));
  for (let i = 0; i < 7; i++) {
    const d = new Date(start); d.setDate(start.getDate() + i);
    const mmdd = `${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
    if (mmdd === aniv) return true;
  }
  return false;
}
function computeStats(data) {
  const map = {};
  const posById = {};
  data.players.forEach((p) => {
    posById[p.id] = p.posicao;
    map[p.id] = { jogos: 0, vitorias: 0, empates: 0, derrotas: 0, gols: 0, assist: 0, craque: 0, sofridos: 0, jogosGol: 0 };
  });
  data.matches.forEach((m) => {
    const w = m.placarA > m.placarB ? "A" : m.placarB > m.placarA ? "B" : "E";
    const run = (ids, team, golsContra) => (ids || []).forEach((id) => {
      if (!map[id]) return; map[id].jogos++;
      if (w === "E") map[id].empates++; else if (w === team) map[id].vitorias++; else map[id].derrotas++;
      if (posById[id] === "GOL") { map[id].jogosGol++; map[id].sofridos += golsContra; }
    });
    run(m.timeA, "A", m.placarB); run(m.timeB, "B", m.placarA);
    Object.entries(m.gols || {}).forEach(([id, n]) => { if (map[id]) map[id].gols += +n || 0; });
    Object.entries(m.assist || {}).forEach(([id, n]) => { if (map[id]) map[id].assist += +n || 0; });
    if (m.craque && map[m.craque]) map[m.craque].craque++;
  });
  Object.values(map).forEach((s) => {
    s.pontos = s.vitorias * 3 + s.empates + s.gols * 2 + s.assist + s.craque * 3;
    s.media = s.jogosGol ? s.sofridos / s.jogosGol : null;
  });
  return map;
}
function balanceTeams(players) {
  const gks = players.filter((p) => p.posicao === "GOL").sort((a, b) => b.overall - a.overall);
  const field = players.filter((p) => p.posicao !== "GOL").sort((a, b) => b.overall - a.overall);
  const teams = [{ players: [], total: 0 }, { players: [], total: 0 }];
  const put = (p, t) => { t.players.push(p); t.total += p.overall || 0; };
  // 1 goleiro TITULAR por time; goleiro que sobrar entra na linha.
  gks.slice(0, 2).forEach((g, i) => put(g, teams[i]));
  [...gks.slice(2), ...field].sort((a, b) => b.overall - a.overall).forEach((p) => {
    put(p, teams[0].total <= teams[1].total ? teams[0] : teams[1]);
  });
  return teams;
}

// Chave canônica de um sorteio (times A/B são intercambiáveis: A×B == B×A).
function teamKey(a, b) {
  const ka = a.map((p) => p.id).sort().join(",");
  const kb = b.map((p) => p.id).sort().join(",");
  return ka < kb ? `${ka}|${kb}` : `${kb}|${ka}`;
}

// Sorteia times equilibrados VARIANDO o resultado e evitando repetir os que já
// saíram (usedKeys). Só repete depois de esgotar as combinações equilibradas.
function balanceTeamsVaried(players, usedKeys) {
  const shuffle = (arr) => {
    const a = [...arr];
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  };
  const gks = players.filter((p) => p.posicao === "GOL");
  const field = players.filter((p) => p.posicao !== "GOL");
  const build = () => {
    const teams = [{ players: [], total: 0 }, { players: [], total: 0 }];
    const put = (p, t) => { t.players.push(p); t.total += p.overall || 0; };
    // 1 goleiro TITULAR por time; goleiro que sobrar joga na linha.
    const gksSh = shuffle(gks);
    gksSh.slice(0, 2).forEach((g, i) => put(g, teams[i]));
    // linha (inclui goleiros extras): ordem embaralhada; mantém tamanhos parelhos e joga no time mais fraco
    shuffle([...field, ...gksSh.slice(2)]).forEach((p) => {
      const sizeDiff = teams[0].players.length - teams[1].players.length;
      const t = sizeDiff >= 1 ? teams[1] : sizeDiff <= -1 ? teams[0]
        : (teams[0].total <= teams[1].total ? teams[0] : teams[1]);
      put(p, t);
    });
    return teams;
  };
  // gera vários candidatos e fica com os mais equilibrados
  const cands = [];
  for (let i = 0; i < 250; i++) {
    const teams = build();
    cands.push({ teams, diff: Math.abs(teams[0].total - teams[1].total), key: teamKey(teams[0].players, teams[1].players) });
  }
  cands.sort((a, b) => a.diff - b.diff);
  const pool = cands.slice(0, Math.max(10, Math.floor(cands.length / 3))); // terço mais equilibrado
  const fresh = pool.filter((c) => !usedKeys.has(c.key));
  const exhausted = fresh.length === 0;          // todas as combinações equilibradas já saíram
  const from = exhausted ? pool : fresh;
  const chosen = from[Math.floor(Math.random() * from.length)];
  return { teams: chosen.teams, key: chosen.key, exhausted };
}

/* PIX BR Code (EMV) — copia e cola válido */
function crc16(str) {
  let crc = 0xffff;
  for (let i = 0; i < str.length; i++) {
    crc ^= str.charCodeAt(i) << 8;
    for (let j = 0; j < 8; j++) { crc = crc & 0x8000 ? (crc << 1) ^ 0x1021 : crc << 1; crc &= 0xffff; }
  }
  return crc.toString(16).toUpperCase().padStart(4, "0");
}
const emv = (id, v) => id + String(v.length).padStart(2, "0") + v;
function pixBRCode({ key, name, city, amount, txid }) {
  const mai = emv("26", emv("00", "br.gov.bcb.pix") + emv("01", key));
  let p =
    emv("00", "01") + mai + emv("52", "0000") + emv("53", "986") +
    (amount ? emv("54", Number(amount).toFixed(2)) : "") +
    emv("58", "BR") + emv("59", noAcc(name || "RECEBEDOR").slice(0, 25)) +
    emv("60", noAcc(city || "TIMBO").slice(0, 15)) +
    emv("62", emv("05", (txid || "***").slice(0, 25)));
  p += "6304";
  return p + crc16(p);
}

