/* ============================ APP ============================ */
export default function App() {
  const [session, setSession] = useState(undefined); // undefined=carregando, null=deslogado
  const [isAdmin, setIsAdmin] = useState(false);
  const [isPresident, setIsPresident] = useState(false);
  const [data, setData] = useState(null);
  const [tab, setTab] = useState("destaques");
  const [notice, setNotice] = useState("");

  // acompanha a sessão de login
  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => setSession(data.session ?? null));
    const { data: sub } = supabase.auth.onAuthStateChange((_e, s) => setSession(s ?? null));
    return () => sub.subscription.unsubscribe();
  }, []);

  // ao logar: descobre o papel, carrega os dados e assina o tempo real
  useEffect(() => {
    if (!session) { setData(null); setIsAdmin(false); setIsPresident(false); return; }
    let unsub = () => {};
    (async () => {
      const admin = await isAdminEmail(session.user.email);
      setIsAdmin(admin);
      isPresidentEmail(session.user.email).then(setIsPresident);
      let d = await fetchData();
      if (!d || !d.players) {              // banco ainda vazio → 1ª configuração
        if (admin) { d = seed(); await pushData(d); }
      }
      setData(d);
      unsub = subscribeData((novo) => setData(novo));
    })();
    return () => unsub();
  }, [session]);

  const update = (fn) => {
    if (!isAdmin) {
      setNotice("Somente a diretoria (presidente/vice) pode editar.");
      setTimeout(() => setNotice(""), 2600);
      return;
    }
    setData((prev) => { const next = typeof fn === "function" ? fn(prev) : fn; pushData(next); return next; });
  };

  if (session === undefined) return <Splash>Conectando…</Splash>;
  if (session === null) return <Login />;
  if (!data) return <Splash>{isAdmin ? "Preparando o vestiário…" : "Aguardando a diretoria configurar o grupo…"}</Splash>;

  // 1º acesso do jogador (não-admin e ainda sem ficha): libera o auto-cadastro.
  // Depois de criado, ele não vê mais esta tela e não pode editar — só o admin.
  const myEmail = (session.user?.email || "").toLowerCase();
  const myPlayer = data.players?.find((p) => (p.email || "").toLowerCase() === myEmail);
  if (!isAdmin && !myPlayer) {
    return <SelfRegister email={myEmail} onDone={async () => setData(await fetchData())} />;
  }

  const stats = computeStats(data);
  const tabs = [
    { k: "destaques", label: "Destaques", Icon: Trophy },
    { k: "elenco", label: "Elenco", Icon: Users },
    { k: "presenca", label: "Próximo jogo", Icon: CalendarCheck },
    { k: "financeiro", label: "Financeiro", Icon: Wallet },
    { k: "partidas", label: "Partidas", Icon: CalendarDays },
    // Sortear é ferramenta da diretoria — só admin vê/usa
    ...(isAdmin ? [{ k: "sortear", label: "Sortear times", Icon: Shuffle }] : []),
  ];

  return (
    <AdminCtx.Provider value={isAdmin}>
    <PresidentCtx.Provider value={isPresident}>
    <MeCtx.Provider value={myEmail}>
    <div style={{ background: T.bg, color: T.bone, minHeight: 640, fontFamily: "'Inter', sans-serif" }}>
      <style>{FONTS}</style>

      {/* Scoreboard header */}
      <div style={{ background: `linear-gradient(180deg, ${T.panel2}, ${T.panel})`, borderBottom: `2px solid ${T.gold}` }}>
        <div className="flex items-center justify-between" style={{ maxWidth: 1040, margin: "0 auto", padding: "6px 18px", borderBottom: `1px solid ${T.line}55` }}>
          <span className="flex items-center gap-1" style={{ ...mono, fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".06em", color: isAdmin ? T.gold : T.muted }}>
            {isAdmin ? <><ShieldCheck size={12} /> Diretoria · edição liberada</> : <><Eye size={12} /> Modo consulta</>}
          </span>
          <span className="flex items-center gap-2" style={{ ...mono, fontSize: 10, color: T.muted }}>
            <span style={{ opacity: 0.7 }}>v{APP_VERSION}</span>
            <span style={{ maxWidth: 160, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{session.user.email}</span>
            <button onClick={() => supabase.auth.signOut()} className="flex items-center gap-1" style={{ color: T.bone, border: `1px solid ${T.line}`, borderRadius: 7, padding: "3px 8px" }}><LogOut size={11} /> Sair</button>
          </span>
        </div>
        <div className="flex items-center justify-between flex-wrap gap-4" style={{ padding: "16px 18px", maxWidth: 1040, margin: "0 auto" }}>
          <div className="flex items-center gap-3">
            <div style={{ borderRadius: 14, background: "#FFFFFF", display: "inline-flex", alignItems: "center", justifyContent: "center", padding: 6, boxShadow: `0 0 0 1px ${T.gold}66` }}>
              <img src={LOGO} alt="Escudo Limitados F.C" style={{ height: 76, width: "auto", display: "block" }} />
            </div>
            <div>
              <div style={{ ...display, fontSize: 38, lineHeight: 0.95, color: T.bone }}>{data.club.nome}</div>
              <div style={{ ...mono, fontSize: 11, color: T.muted }}>PELADA DE QUINTA · {data.club.cidade}</div>
            </div>
          </div>
          <div className="flex items-center gap-4" style={{ margin: "0 auto" }}>
            <div style={{ textAlign: "center" }}>
              <div className="flex items-center justify-center gap-1" style={{ ...mono, fontSize: 9, color: T.gold, textTransform: "uppercase", letterSpacing: ".08em" }}><Crown size={11} /> Presidente</div>
              <div style={{ ...display, fontSize: 24, color: T.bone, lineHeight: 1, marginTop: 2 }}>{data.club.presidente || "Samyr"}</div>
            </div>
            <div style={{ width: 1, height: 34, background: T.line }} />
            <div style={{ textAlign: "center" }}>
              <div className="flex items-center justify-center gap-1" style={{ ...mono, fontSize: 9, color: T.blue, textTransform: "uppercase", letterSpacing: ".08em" }}><Shield size={11} /> Vice</div>
              <div style={{ ...display, fontSize: 24, color: T.bone, lineHeight: 1, marginTop: 2 }}>{data.club.vice || "Marcelo"}</div>
            </div>
          </div>
          <div className="text-right">
            <div style={{ ...mono, fontSize: 10, color: T.muted, textTransform: "uppercase" }}>Caixa do grupo</div>
            <div style={{ ...display, fontSize: 26, color: data.club.caixa >= 0 ? T.turf : T.red }}>{brl(data.club.caixa)}</div>
          </div>
        </div>
        {/* Tabs */}
        <div style={{ maxWidth: 1040, margin: "0 auto", padding: "0 10px", display: "flex", gap: 4, overflowX: "auto" }}>
          {tabs.map(({ k, label, Icon }) => (
            <button key={k} onClick={() => setTab(k)} className="flex items-center gap-2" style={{
              padding: "10px 14px", whiteSpace: "nowrap", borderBottom: `2px solid ${tab === k ? T.gold : "transparent"}`,
              color: tab === k ? T.bone : T.muted, ...mono, fontSize: 12, fontWeight: 700, textTransform: "uppercase",
            }}><Icon size={15} /> {label}</button>
          ))}
        </div>
      </div>

      <div style={{ maxWidth: 1040, margin: "0 auto", padding: 18 }}>
        {tab === "destaques" && <Destaques data={data} stats={stats} />}
        {tab === "elenco" && <Elenco data={data} update={update} />}
        {tab === "presenca" && <Presenca data={data} update={update} />}
        {tab === "financeiro" && <Financeiro data={data} update={update} />}
        {tab === "partidas" && <Partidas data={data} update={update} stats={stats} />}
        {tab === "sortear" && isAdmin && <Sortear data={data} update={update} />}
      </div>

      <div style={{ textAlign: "center", padding: "10px 0 24px", ...mono, fontSize: 10, color: T.line }}>
        Limitados F.C · dados compartilhados em tempo real
      </div>

      {notice && (
        <div style={{ position: "fixed", left: "50%", bottom: 22, transform: "translateX(-50%)", background: T.panel2, color: T.bone, border: `1px solid ${T.amber}`, borderRadius: 10, padding: "10px 16px", fontSize: 13, boxShadow: "0 8px 24px rgba(0,0,0,.4)", zIndex: 80 }}>
          {notice}
        </div>
      )}
    </div>
    </MeCtx.Provider>
    </PresidentCtx.Provider>
    </AdminCtx.Provider>
  );
}

/* ============================ SPLASH + LOGIN ============================ */
function Splash({ children }) {
  return (
    <div style={{ background: T.bg, color: T.muted, minHeight: 460, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "'Inter', sans-serif" }}>
      <style>{FONTS}</style>{children}
    </div>
  );
}

function Login() {
  const [email, setEmail] = useState("");
  const [sent, setSent] = useState(false);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const enviar = async () => {
    if (!email) return;
    setBusy(true); setErr("");
    const { error } = await supabase.auth.signInWithOtp({ email: email.trim().toLowerCase(), options: { emailRedirectTo: window.location.origin + import.meta.env.BASE_URL } });
    setBusy(false);
    if (error) {
      const m = (error.message || "").trim();
      // 500/erro de envio vem vazio ou como "{}"; mostra mensagem amigável
      setErr(!m || m === "{}" ? "Não foi possível enviar o e-mail agora (falha no envio). Tente de novo em instantes." : m);
    } else setSent(true);
  };
  return (
    <div style={{ background: T.bg, minHeight: 560, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "'Inter', sans-serif", padding: 20 }}>
      <style>{FONTS}</style>
      <div style={{ width: "100%", maxWidth: 380, textAlign: "center" }}>
        <div style={{ borderRadius: 16, background: "#FFFFFF", display: "inline-flex", padding: 10, boxShadow: `0 0 0 1px ${T.gold}66`, marginBottom: 18 }}>
          <img src={LOGO} alt="Escudo Limitados F.C" style={{ height: 96, width: "auto", display: "block" }} />
        </div>
        <div style={{ ...display, fontSize: 40, color: T.bone, lineHeight: 0.95 }}>Limitados F.C</div>
        <div style={{ ...mono, fontSize: 11, color: T.muted, marginBottom: 24 }}>PELADA DE QUINTA</div>

        {sent ? (
          <div style={{ background: T.panel, border: `1px solid ${T.turf}55`, borderRadius: 12, padding: 20, color: T.bone }}>
            <Mail size={26} color={T.turf} style={{ margin: "0 auto 10px" }} />
            <div style={{ fontSize: 15, fontWeight: 600, marginBottom: 6 }}>Link enviado!</div>
            <div style={{ fontSize: 13, color: T.muted }}>Abra o e-mail <b style={{ color: T.bone }}>{email}</b> e toque no link para entrar.</div>
          </div>
        ) : (
          <div style={{ background: T.panel, border: `1px solid ${T.line}`, borderRadius: 12, padding: 20 }}>
            <div style={{ fontSize: 13, color: T.muted, marginBottom: 12 }}>Entre com seu e-mail para acessar o grupo:</div>
            <input type="email" placeholder="seu@email.com" value={email}
              onChange={(e) => setEmail(e.target.value)} onKeyDown={(e) => e.key === "Enter" && enviar()}
              style={{ width: "100%", background: T.bg, border: `1px solid ${T.line}`, color: T.bone, borderRadius: 9, padding: "11px 12px", fontSize: 14, outline: "none", marginBottom: 12 }} />
            <button onClick={enviar} disabled={busy} className="flex items-center justify-center gap-2"
              style={{ width: "100%", background: T.gold, color: T.bg, fontWeight: 700, fontSize: 14, padding: "11px 16px", borderRadius: 10, opacity: busy ? 0.6 : 1 }}>
              <Mail size={16} /> {busy ? "Enviando…" : "Receber link de acesso"}
            </button>
            {err && <div style={{ color: T.red, fontSize: 12, marginTop: 10 }}>{err}</div>}
            <div style={{ ...mono, fontSize: 10, color: T.muted, marginTop: 14 }}>Sem senha: você recebe um link por e-mail.</div>
          </div>
        )}

        {!(typeof window !== "undefined" && window.Capacitor?.isNativePlatform?.()) && (
          <a href="https://github.com/samyrfergusson/limitados-fc-android/releases/download/latest/app-debug.apk"
            className="flex items-center justify-center gap-2"
            style={{ marginTop: 16, width: "100%", boxSizing: "border-box", textDecoration: "none", color: T.turf, border: `1px solid ${T.turf}66`, background: T.turf + "12", fontWeight: 700, fontSize: 13, padding: "10px 16px", borderRadius: 10 }}>
            <Download size={15} /> Baixar app para Android (APK)
          </a>
        )}
      </div>
    </div>
  );
}

/* ============================ AUTO-CADASTRO (1º ACESSO) ============================ */
function SelfRegister({ email, onDone }) {
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);
  const salvar = async (pl) => {
    if (busy) return;
    setBusy(true); setErr("");
    const res = await selfRegister({ ...pl, email });
    setBusy(false);
    if (res.ok) onDone();
    else setErr(res.error || "Não foi possível concluir o cadastro. Tente novamente.");
  };
  const heading = (
    <div style={{ marginBottom: 16 }}>
      <div style={{ fontSize: 13, color: T.muted }}>
        Preencha sua ficha para entrar no elenco. Você faz isto <b style={{ color: T.bone }}>uma única vez</b> —
        depois disso, qualquer alteração é feita pela diretoria.
      </div>
      {err && <div style={{ color: T.red, fontSize: 12, marginTop: 8 }}>{err}</div>}
    </div>
  );
  return (
    <div style={{ background: T.bg, minHeight: 560, fontFamily: "'Inter', sans-serif", padding: 16, overflowY: "auto" }}>
      <style>{FONTS}</style>
      <div style={{ maxWidth: 620, margin: "0 auto" }}>
        <div style={{ textAlign: "center", padding: "16px 0 18px" }}>
          <div style={{ ...display, fontSize: 34, color: T.bone, lineHeight: 1 }}>Bem-vindo ao Limitados F.C</div>
          <div style={{ ...mono, fontSize: 11, color: T.muted, marginTop: 4 }}>{email}</div>
        </div>
        <div style={{ background: T.panel, border: `1px solid ${T.line}`, borderRadius: 16, padding: 18 }}>
          <PlayerForm embed heading={heading} submitLabel={busy ? "Enviando…" : "Entrar no elenco"} onSave={salvar} />
        </div>
        <div style={{ textAlign: "center", marginTop: 14 }}>
          <button onClick={() => supabase.auth.signOut()} style={{ ...mono, fontSize: 11, color: T.muted, border: `1px solid ${T.line}`, borderRadius: 8, padding: "6px 12px" }}>
            <LogOut size={11} style={{ display: "inline", marginRight: 4 }} /> Sair
          </button>
        </div>
      </div>
    </div>
  );
}

/* ============================ DESTAQUES ============================ */
function Destaques({ data, stats }) {
  const active = data.players.filter((p) => p.status === "ativo");
  const byId = (id) => data.players.find((p) => p.id === id);
  const ranked = active.map((p) => ({ p, s: stats[p.id] })).sort((a, b) => b.s.pontos - a.s.pontos);
  const artilheiros = [...ranked].sort((a, b) => b.s.gols - a.s.gols).filter((x) => x.s.gols > 0).slice(0, 5);
  const garcom = [...ranked].sort((a, b) => b.s.assist - a.s.assist).filter((x) => x.s.assist > 0).slice(0, 3);
  const lastMatch = [...data.matches].sort((a, b) => (a.data < b.data ? 1 : -1))[0];
  const craque = lastMatch?.craque ? byId(lastMatch.craque) : null;
  const nivers = data.players.filter((p) => isBirthdayThisWeek(p.aniversario));
  const maxGols = Math.max(1, ...artilheiros.map((x) => x.s.gols));
  const goleiros = active.filter((p) => p.posicao === "GOL" && stats[p.id].jogosGol > 0)
    .map((p) => ({ p, s: stats[p.id] })).sort((a, b) => a.s.media - b.s.media);
  const menosVazado = goleiros[0], maisVazado = goleiros.length > 1 ? goleiros[goleiros.length - 1] : null;

  return (
    <div className="grid gap-4" style={{ gridTemplateColumns: "repeat(auto-fit,minmax(280px,1fr))" }}>
      {/* Craque da semana */}
      <Card style={{ padding: 18, gridColumn: "1 / -1" }}>
        <div className="grid gap-4" style={{ gridTemplateColumns: "repeat(auto-fit,minmax(220px,1fr))" }}>
          <Highlight Icon={Star} color={T.gold} title="Craque da semana"
            main={craque ? craque.apelido : "—"} sub={craque ? `MVP · ${new Date(lastMatch.data).toLocaleDateString("pt-BR")}` : "sem partida"} big />
          <Highlight Icon={Cake} color={T.blue} title="Aniversariante da semana"
            main={nivers.length ? nivers.map((n) => n.apelido).join(", ") : "ninguém 🎂"}
            sub={nivers.length ? "manda o parabéns no grupo!" : "semana sem bolo"} />
          <Highlight Icon={Target} color={T.red} title="Artilheiro"
            main={artilheiros[0]?.p.apelido || "—"} sub={artilheiros[0] ? `${artilheiros[0].s.gols} gols na temporada` : "—"} />
        </div>
      </Card>

      {/* Artilharia */}
      <Card style={{ padding: 18 }}>
        <SectionTitle Icon={Target} color={T.red}>Artilharia</SectionTitle>
        {artilheiros.length === 0 && <Empty>Registre uma partida com gols para ver a artilharia.</Empty>}
        {artilheiros.map(({ p, s }, i) => (
          <div key={p.id} className="flex items-center gap-3" style={{ marginBottom: 10 }}>
            <span style={{ ...display, fontSize: 20, color: i === 0 ? T.gold : T.muted, width: 22 }}>{i + 1}</span>
            <Jersey p={p} size={34} />
            <div style={{ flex: 1 }}>
              <div className="flex items-center justify-between">
                <span style={{ fontWeight: 600, fontSize: 14 }}>{p.apelido}</span>
                <span style={{ ...mono, color: T.red, fontWeight: 700 }}>{s.gols}</span>
              </div>
              <div style={{ height: 6, background: T.bg, borderRadius: 4, marginTop: 4 }}>
                <div style={{ height: 6, width: `${(s.gols / maxGols) * 100}%`, background: T.red, borderRadius: 4 }} />
              </div>
            </div>
          </div>
        ))}
      </Card>

      {/* Ranking geral */}
      <Card style={{ padding: 18 }}>
        <SectionTitle Icon={TrendingUp} color={T.turf}>Ranking geral</SectionTitle>
        <div style={{ ...mono, fontSize: 10, color: T.muted, marginBottom: 8 }}>PONTOS = 3·vitória + empate + 2·gol + assist + 3·craque</div>
        <div style={{ display: "grid", gridTemplateColumns: "22px 1fr repeat(4,26px) 40px", gap: 6, ...mono, fontSize: 10, color: T.muted, paddingBottom: 6, borderBottom: `1px solid ${T.line}` }}>
          <span>#</span><span>Jogador</span><span className="text-center">J</span><span className="text-center">G</span><span className="text-center">A</span><span className="text-center">★</span><span className="text-center">PTS</span>
        </div>
        {ranked.slice(0, 8).map(({ p, s }, i) => (
          <div key={p.id} style={{ display: "grid", gridTemplateColumns: "22px 1fr repeat(4,26px) 40px", gap: 6, alignItems: "center", padding: "7px 0", borderBottom: `1px solid ${T.line}55` }}>
            <span style={{ ...display, fontSize: 16, color: i === 0 ? T.gold : T.muted }}>{i + 1}</span>
            <span style={{ fontSize: 13 }}>{p.apelido}</span>
            {[s.jogos, s.gols, s.assist, s.craque].map((v, j) => (
              <span key={j} className="text-center" style={{ ...mono, fontSize: 12, color: T.muted }}>{v}</span>
            ))}
            <span className="text-center" style={{ ...mono, fontSize: 13, fontWeight: 700, color: T.turf }}>{s.pontos}</span>
          </div>
        ))}
      </Card>

      {/* Garçom */}
      <Card style={{ padding: 18 }}>
        <SectionTitle Icon={Handshake} color={T.blue}>Garçom (assistências)</SectionTitle>
        {garcom.length === 0 && <Empty>Sem assistências registradas ainda.</Empty>}
        {garcom.map(({ p, s }, i) => (
          <div key={p.id} className="flex items-center gap-3" style={{ marginBottom: 10 }}>
            <span style={{ ...display, fontSize: 18, color: i === 0 ? T.gold : T.muted, width: 20 }}>{i + 1}</span>
            <Jersey p={p} size={32} />
            <span style={{ flex: 1, fontSize: 14, fontWeight: 600 }}>{p.apelido}</span>
            <span style={{ ...mono, color: T.blue, fontWeight: 700 }}>{s.assist}</span>
          </div>
        ))}
      </Card>

      {/* Goleiros */}
      <Card style={{ padding: 18 }}>
        <SectionTitle Icon={Goal} color={T.gold}>Goleiros · gols sofridos</SectionTitle>
        {goleiros.length === 0 && <Empty>Escale goleiros nas partidas para ver o ranking.</Empty>}
        {goleiros.length > 0 && (
          <div className="grid gap-2" style={{ gridTemplateColumns: maisVazado ? "1fr 1fr" : "1fr", marginBottom: 14 }}>
            <div style={{ background: T.bg, border: `1px solid ${T.turf}44`, borderRadius: 10, padding: 12 }}>
              <div style={{ ...mono, fontSize: 10, color: T.turf, textTransform: "uppercase", fontWeight: 700 }}>🧤 Menos vazado</div>
              <div style={{ ...display, fontSize: 26, color: T.bone, marginTop: 4, lineHeight: 1 }}>{menosVazado.p.apelido}</div>
              <div style={{ ...mono, fontSize: 11, color: T.muted, marginTop: 3 }}>{menosVazado.s.media.toFixed(1)} por jogo · {menosVazado.s.sofridos} em {menosVazado.s.jogosGol}</div>
            </div>
            {maisVazado && (
              <div style={{ background: T.bg, border: `1px solid ${T.red}44`, borderRadius: 10, padding: 12 }}>
                <div style={{ ...mono, fontSize: 10, color: T.red, textTransform: "uppercase", fontWeight: 700 }}>🎯 Mais vazado</div>
                <div style={{ ...display, fontSize: 26, color: T.bone, marginTop: 4, lineHeight: 1 }}>{maisVazado.p.apelido}</div>
                <div style={{ ...mono, fontSize: 11, color: T.muted, marginTop: 3 }}>{maisVazado.s.media.toFixed(1)} por jogo · {maisVazado.s.sofridos} em {maisVazado.s.jogosGol}</div>
              </div>
            )}
          </div>
        )}
        {goleiros.map(({ p, s }, i) => (
          <div key={p.id} className="flex items-center gap-3" style={{ padding: "6px 0", borderBottom: `1px solid ${T.line}55` }}>
            <span style={{ ...display, fontSize: 18, color: i === 0 ? T.turf : T.muted, width: 20 }}>{i + 1}</span>
            <Jersey p={p} size={30} />
            <div style={{ flex: 1 }}>
              <span style={{ fontSize: 14, fontWeight: 600 }}>{p.apelido}</span>
              <span style={{ ...mono, fontSize: 10, color: T.muted, marginLeft: 6 }}>{s.jogosGol} jogos</span>
            </div>
            <span style={{ ...mono, fontSize: 12, color: T.muted }}>{s.sofridos} GS</span>
            <span style={{ ...mono, fontWeight: 700, color: i === 0 ? T.turf : i === goleiros.length - 1 ? T.red : T.bone, width: 34, textAlign: "right" }}>{s.media.toFixed(1)}</span>
          </div>
        ))}
      </Card>
    </div>
  );
}
const Highlight = ({ Icon, color, title, main, sub, big }) => (
  <div style={{ background: T.bg, border: `1px solid ${color}33`, borderRadius: 12, padding: 14 }}>
    <div className="flex items-center gap-2" style={{ color, ...mono, fontSize: 11, textTransform: "uppercase", fontWeight: 700 }}><Icon size={14} /> {title}</div>
    <div style={{ ...display, fontSize: big ? 34 : 24, color: T.bone, marginTop: 6, lineHeight: 1 }}>{main}</div>
    <div style={{ ...mono, fontSize: 11, color: T.muted, marginTop: 4 }}>{sub}</div>
  </div>
);
const SectionTitle = ({ Icon, color, children }) => (
  <div className="flex items-center gap-2" style={{ marginBottom: 14 }}>
    <Icon size={18} color={color} /><h3 style={{ ...display, fontSize: 22, color: T.bone }}>{children}</h3>
  </div>
);
const Empty = ({ children }) => <div style={{ ...mono, fontSize: 12, color: T.muted, padding: "8px 0" }}>{children}</div>;

/* ============================ ELENCO ============================ */
function Elenco({ data, update }) {
  const isAdmin = useIsAdmin();
  const [edit, setEdit] = useState(null); // player or "new"
  const active = data.players.filter((p) => p.status === "ativo").sort((a, b) => b.overall - a.overall);
  const inactive = data.players.filter((p) => p.status !== "ativo");

  const save = (pl) => update((d) => {
    const exists = d.players.some((x) => x.id === pl.id);
    return { ...d, players: exists ? d.players.map((x) => (x.id === pl.id ? pl : x)) : [...d.players, pl] };
  });
  const toggle = (p) => update((d) => ({
    ...d, players: d.players.map((x) => x.id === p.id ? { ...x, status: x.status === "ativo" ? "inativo" : "ativo", dataSaida: x.status === "ativo" ? new Date().toISOString().slice(0, 10) : null } : x),
  }));
  const del = (p) => { if (confirm(`Remover ${p.apelido} de vez?`)) update((d) => ({ ...d, players: d.players.filter((x) => x.id !== p.id) })); };

  return (
    <div>
      <div className="flex items-center justify-between" style={{ marginBottom: 14 }}>
        <SectionTitle Icon={Users} color={T.turf}>Elenco · {active.length} ativos</SectionTitle>
        {isAdmin && <PrimaryBtn onClick={() => setEdit("new")}><Plus size={16} /> Novo jogador</PrimaryBtn>}
      </div>
      <div className="grid gap-3" style={{ gridTemplateColumns: "repeat(auto-fill,minmax(300px,1fr))" }}>
        {active.map((p) => <PlayerCard key={p.id} p={p} onEdit={() => setEdit(p)} onToggle={() => toggle(p)} onDel={() => del(p)} />)}
      </div>
      {inactive.length > 0 && (
        <>
          <div style={{ ...display, fontSize: 20, color: T.muted, margin: "22px 0 10px" }}>Ex-integrantes / afastados</div>
          <div className="grid gap-3" style={{ gridTemplateColumns: "repeat(auto-fill,minmax(300px,1fr))" }}>
            {inactive.map((p) => <PlayerCard key={p.id} p={p} onEdit={() => setEdit(p)} onToggle={() => toggle(p)} onDel={() => del(p)} faded />)}
          </div>
        </>
      )}
      {edit && <PlayerForm player={edit === "new" ? null : edit} onClose={() => setEdit(null)} onSave={(pl) => { save(pl); setEdit(null); }} />}
    </div>
  );
}
function PlayerCard({ p, onEdit, onToggle, onDel, faded }) {
  const admin = useIsAdmin();
  const me = useMe();
  const c = CARGO[p.cargo] || CARGO.mensalista;
  // O próprio jogador (não-admin) pode ajustar seu X1 uma única vez (p.x1Set trava depois).
  const canEditX1 = !admin && !!me && (p.email || "").toLowerCase() === me.toLowerCase() && !p.x1Set;
  const [x1val, setX1val] = useState(p.atr?.dri ?? 70);
  const [x1busy, setX1busy] = useState(false);
  const [x1err, setX1err] = useState("");
  const saveX1 = async () => {
    setX1busy(true); setX1err("");
    const res = await setMyX1(Number(x1val));
    setX1busy(false);
    if (!res.ok) setX1err(res.error || "Não foi possível salvar.");
  };
  // Estrela da Patota — só o presidente promove/remove (nem outros admins).
  const president = useIsPresident();
  const [estBusy, setEstBusy] = useState(false);
  const toggleEstrela = async () => {
    setEstBusy(true);
    const res = await setEstrela(p.id, !p.estrela);
    setEstBusy(false);
    if (!res.ok) alert(res.error || "Não foi possível alterar a estrela.");
  };
  return (
    <Card style={{ padding: 14, opacity: faded ? 0.55 : 1 }}>
      <div className="flex gap-3">
        <Jersey p={p} size={46} />
        <div style={{ flex: 1, minWidth: 0 }}>
          <div className="flex items-center gap-2">
            <span style={{ fontWeight: 700, fontSize: 15 }}>{p.apelido}</span>
            {admin && <span style={{ ...display, fontSize: 20, color: T.gold, marginLeft: "auto" }}>{p.overall}</span>}
          </div>
          {(p.estrela || president) && (
            <div className="flex items-center gap-2 flex-wrap" style={{ marginTop: 4, justifyContent: "flex-end" }}>
              {p.estrela && (
                <span style={{ ...mono, fontSize: 9, fontWeight: 700, color: T.gold, border: `1px solid ${T.gold}`, background: T.gold + "1a", borderRadius: 999, padding: "2px 8px", display: "inline-flex", alignItems: "center", gap: 3 }}>
                  <Star size={10} fill={T.gold} color={T.gold} /> ESTRELA DA PATOTA
                </span>
              )}
              {president && (
                <button onClick={toggleEstrela} disabled={estBusy} style={{ ...mono, fontSize: 9, fontWeight: 700, color: p.estrela ? T.red : T.gold, border: `1px solid ${(p.estrela ? T.red : T.gold)}66`, borderRadius: 7, padding: "2px 7px", opacity: estBusy ? 0.6 : 1, background: "transparent" }}>
                  {estBusy ? "…" : (p.estrela ? "remover" : "⭐ promover")}
                </button>
              )}
            </div>
          )}
          <div style={{ fontSize: 12, color: T.muted, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{p.nome}</div>
          <div className="flex items-center gap-1 flex-wrap" style={{ marginTop: 6 }}>
            <Pill color={POS[p.posicao]}>{POS_LABEL[p.posicao]}</Pill>
            <Pill color={c.color} filled={["presidente", "suplente", "admin"].includes(p.cargo)}>{c.label}</Pill>
            {!p.mensalista && <Pill color={T.amber}>diarista</Pill>}
          </div>
        </div>
      </div>
      {/* atributos mini */}
      <div className="grid" style={{ gridTemplateColumns: "repeat(6,1fr)", gap: 6, marginTop: 12 }}>
        {[["VEL", p.atr?.vel], ["FIN", p.atr?.fin], ["PAS", p.atr?.pas], ["DEF", p.atr?.def], ["FIS", p.atr?.fis], ["X1", p.atr?.dri]].map(([k, v]) => (
          <div key={k} style={{ textAlign: "center" }}>
            <div style={{ ...mono, fontSize: 9, color: T.muted }}>{k}</div>
            <div style={{ ...mono, fontSize: 13, fontWeight: 700, color: (v || 0) >= 80 ? T.turf : T.bone }}>{v || "–"}</div>
          </div>
        ))}
      </div>
      {canEditX1 && (
        <div style={{ marginTop: 10, padding: 10, borderRadius: 10, background: T.panel2, border: `1px solid ${T.gold}66` }}>
          <div style={{ ...mono, fontSize: 10, color: T.gold, marginBottom: 6 }}>⚡ Ajuste seu X1 — só pode 1 vez!</div>
          <div className="flex items-center gap-2">
            <input type="number" min="1" max="99" value={x1val} onChange={(e) => setX1val(e.target.value)}
              style={{ ...inputStyle, width: 72, textAlign: "center", padding: "6px 4px" }} />
            <button onClick={saveX1} disabled={x1busy} style={{ ...smallBtn(T.turf), opacity: x1busy ? 0.6 : 1 }}>
              <Check size={11} /> {x1busy ? "Salvando…" : "Salvar meu X1"}
            </button>
          </div>
          {x1err && <div style={{ color: T.red, fontSize: 11, marginTop: 6 }}>{x1err}</div>}
        </div>
      )}
      <div className="flex items-center gap-2" style={{ marginTop: 12, ...mono, fontSize: 10, color: T.muted }}>
        <span>desde {new Date(p.dataEntrada).toLocaleDateString("pt-BR", { month: "2-digit", year: "2-digit" })}</span>
        {p.dataSaida && <span style={{ color: T.red }}>· saiu {new Date(p.dataSaida).toLocaleDateString("pt-BR", { month: "2-digit", year: "2-digit" })}</span>}
        <div className="flex gap-1" style={{ marginLeft: "auto" }}>
          <IconBtn onClick={onEdit} title="Editar"><ClipboardList size={14} /></IconBtn>
          <IconBtn onClick={onToggle} title={p.status === "ativo" ? "Afastar" : "Reativar"}><Power size={14} color={p.status === "ativo" ? T.amber : T.turf} /></IconBtn>
          <IconBtn onClick={onDel} title="Remover"><Trash2 size={14} color={T.red} /></IconBtn>
        </div>
      </div>
    </Card>
  );
}
function PlayerForm({ player, onClose, onSave, embed, heading, submitLabel }) {
  const [f, setF] = useState(player || {
    id: uid(), nome: "", apelido: "", numero: "", posicao: "MEI", overall: 75, cargo: "mensalista",
    mensalista: true, status: "ativo", dataEntrada: new Date().toISOString().slice(0, 10), dataSaida: null,
    aniversario: "", atr: { vel: 70, fin: 70, pas: 70, def: 70, fis: 70, dri: 70 },
  });
  const set = (k, v) => setF((x) => ({ ...x, [k]: v }));
  // Guarda o texto cru enquanto edita (deixa apagar tudo/ficar vazio);
  // a conversão para número acontece só ao salvar (submit).
  const setAtr = (k, v) => setF((x) => ({ ...x, atr: { ...x.atr, [k]: v } }));
  const president = useIsPresident(); // só o presidente promove a cargos elevados
  const submit = () => onSave({
    ...f,
    overall: Number(f.overall) || 0,
    atr: Object.fromEntries(Object.entries(f.atr).map(([k, v]) => [k, Number(v) || 0])),
  });
  const body = (
    <>
      {heading}
      <div className="grid gap-3" style={{ gridTemplateColumns: "1fr 1fr" }}>
        <Field label="Nome completo"><input style={inputStyle} value={f.nome} onChange={(e) => set("nome", e.target.value)} /></Field>
        <Field label="Apelido"><input style={inputStyle} value={f.apelido} onChange={(e) => set("apelido", e.target.value)} /></Field>
        <Field label="Camisa nº"><input type="number" style={inputStyle} value={f.numero} onChange={(e) => set("numero", e.target.value)} /></Field>
        <Field label="Posição">
          <select style={inputStyle} value={f.posicao} onChange={(e) => set("posicao", e.target.value)}>
            {Object.entries(POS_LABEL).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
          </select>
        </Field>
        {!embed && <Field label={`Overall (peso): ${f.overall}`}><input type="range" min="40" max="99" style={{ width: "100%" }} value={f.overall} onChange={(e) => set("overall", +e.target.value)} /></Field>}
        <Field label="Aniversário (MM-DD)"><input placeholder="07-16" style={inputStyle} value={f.aniversario} onChange={(e) => set("aniversario", e.target.value)} /></Field>
        <Field label="Cargo">
          <select style={inputStyle} value={f.cargo} onChange={(e) => set("cargo", e.target.value)}>
            {Object.entries(CARGO)
              // mensalista/diarista sempre; o cargo atual (evita apagar sem querer);
              // cargos elevados (presidente/vice/admin) SÓ o presidente promove
              .filter(([k]) => k === "mensalista" || k === "diarista" || k === "convidado" || k === f.cargo || (!embed && president))
              .map(([k, v]) => <option key={k} value={k}>{v.label}</option>)}
          </select>
        </Field>
        <Field label="Tipo">
          <select style={inputStyle} value={f.mensalista ? "1" : "0"} onChange={(e) => set("mensalista", e.target.value === "1")}>
            <option value="1">Mensalista</option><option value="0">Diarista</option>
          </select>
        </Field>
      </div>
      <div style={{ ...mono, fontSize: 11, color: T.muted, textTransform: "uppercase", margin: "6px 0 8px" }}>Características</div>
      <div className="grid" style={{ gridTemplateColumns: "repeat(6,1fr)", gap: 8 }}>
        {[["vel", "VEL"], ["fin", "FIN"], ["pas", "PAS"], ["def", "DEF"], ["fis", "FIS"], ["dri", "X1"]].map(([k, lb]) => (
          <div key={k} style={{ textAlign: "center" }}>
            <div style={{ ...mono, fontSize: 10, color: T.muted }}>{lb}</div>
            <input type="number" min="1" max="99" style={{ ...inputStyle, textAlign: "center", padding: "6px 2px" }} value={f.atr?.[k] ?? ""} onChange={(e) => setAtr(k, e.target.value)} />
          </div>
        ))}
      </div>
      <div className="flex gap-2" style={{ marginTop: 18 }}>
        <PrimaryBtn onClick={submit} full>{submitLabel || "Salvar"}</PrimaryBtn>
        {!embed && <GhostBtn onClick={onClose}>Cancelar</GhostBtn>}
      </div>
    </>
  );
  if (embed) return body;
  return <Modal title={player ? "Editar jogador" : "Novo jogador"} onClose={onClose} wide>{body}</Modal>;
}

/* ============================ PRESENÇA / PRÓXIMO JOGO ============================ */
const smallBtn = (c) => ({ ...mono, fontSize: 10, fontWeight: 700, color: c, border: `1px solid ${c}55`, borderRadius: 8, background: c + "12", padding: "6px 10px", display: "flex", alignItems: "center", gap: 4 });
const RSVP = {
  vou: { label: "Vou", color: T.turf, Icon: ThumbsUp },
  duvida: { label: "Dúvida", color: T.amber, Icon: HelpCircle },
  fora: { label: "Fora", color: T.red, Icon: ThumbsDown },
};
function Presenca({ data, update }) {
  const isAdmin = useIsAdmin();
  const me = useMe();
  const [closing, setClosing] = useState(false);
  const [rsvpBusy, setRsvpBusy] = useState(false);
  const [rsvpErr, setRsvpErr] = useState("");
  const jogo = data.proximoJogo;
  const active = data.players.filter((p) => p.status === "ativo");
  // Jogador logado (para confirmar a própria presença).
  const myPlayer = data.players.find((p) => (p.email || "").toLowerCase() === (me || "").toLowerCase());
  const confirmarMinha = async (k) => {
    if (!myPlayer) return;
    setRsvpBusy(true); setRsvpErr("");
    const cur = jogo.rsvp?.[myPlayer.id]?.s;
    const res = await setMyRsvp(cur === k ? null : k); // toca de novo no mesmo = desmarca
    setRsvpBusy(false);
    if (!res.ok) setRsvpErr(res.error || "Não foi possível confirmar.");
  };
  const setJogo = (k, v) => update((d) => ({ ...d, proximoJogo: { ...d.proximoJogo, [k]: v } }));
  const setRegra = (k, v) => update((d) => ({ ...d, regras: { ...d.regras, [k]: +v || 0 } }));
  const setRsvp = (id, s) => update((d) => {
    const cur = d.proximoJogo.rsvp[id]; const rsvp = { ...d.proximoJogo.rsvp };
    if (cur?.s === s) delete rsvp[id]; else rsvp[id] = { s, at: cur?.at || Date.now() };
    return { ...d, proximoJogo: { ...d.proximoJogo, rsvp } };
  });
  const list = (s) => active.filter((p) => jogo.rsvp[p.id]?.s === s).sort((a, b) => jogo.rsvp[a.id].at - jogo.rsvp[b.id].at);
  const vou = list("vou"), duvida = list("duvida"), fora = list("fora");
  const semResp = active.filter((p) => !jogo.rsvp[p.id]);
  const confirmados = vou.slice(0, jogo.vagas), espera = vou.slice(jogo.vagas);
  const dt = new Date(jogo.data + "T" + (jogo.hora || "20:00"));
  const dataFmt = dt.toLocaleDateString("pt-BR", { weekday: "long", day: "2-digit", month: "long" });

  const RsvpToggle = ({ p }) => (
    <div className="flex gap-1">
      {Object.entries(RSVP).map(([k, v]) => {
        const on = jogo.rsvp[p.id]?.s === k;
        return (
          <button key={k} onClick={() => setRsvp(p.id, k)} title={v.label} style={{
            width: 26, height: 24, borderRadius: 6, border: `1px solid ${on ? v.color : T.line}`,
            background: on ? v.color + "22" : "transparent", display: "flex", alignItems: "center", justifyContent: "center",
          }}><v.Icon size={12} color={on ? v.color : T.muted} /></button>
        );
      })}
    </div>
  );
  const cols = [["Confirmados", T.turf, confirmados], ["Lista de espera", T.amber, espera], ["Dúvida", T.amber, duvida], ["Fora", T.red, fora], ["Sem resposta", T.muted, semResp]];

  return (
    <div>
      <Card style={{ padding: 18, marginBottom: 16 }}>
        <div className="flex items-start justify-between flex-wrap gap-3">
          <div>
            <div style={{ ...mono, fontSize: 11, color: T.turf, textTransform: "uppercase", letterSpacing: ".08em" }}>Próximo jogo</div>
            <div style={{ ...display, fontSize: 34, color: T.bone, lineHeight: 1, textTransform: "capitalize" }}>{dataFmt}</div>
            <div style={{ ...mono, fontSize: 13, color: T.muted, marginTop: 4 }}>{jogo.hora} · {jogo.local}</div>
          </div>
          <div style={{ textAlign: "right" }}>
            <div style={{ ...display, fontSize: 34, color: espera.length ? T.amber : T.turf }}>{confirmados.length}/{jogo.vagas}</div>
            <div style={{ ...mono, fontSize: 11, color: T.muted }}>confirmados{espera.length ? ` · ${espera.length} na espera` : ""}</div>
          </div>
        </div>
        <div className="grid gap-2" style={{ gridTemplateColumns: "repeat(auto-fit,minmax(120px,1fr))", marginTop: 14 }}>
          <Field label="Data"><input type="date" style={inputStyle} value={jogo.data} onChange={(e) => setJogo("data", e.target.value)} /></Field>
          <Field label="Hora"><input type="time" style={inputStyle} value={jogo.hora} onChange={(e) => setJogo("hora", e.target.value)} /></Field>
          <Field label="Local"><input style={inputStyle} value={jogo.local} onChange={(e) => setJogo("local", e.target.value)} /></Field>
          <Field label="Vagas"><input type="number" style={inputStyle} value={jogo.vagas} onChange={(e) => setJogo("vagas", +e.target.value)} /></Field>
        </div>
      </Card>

      {myPlayer && (
        <Card style={{ padding: 16, marginBottom: 16, borderColor: T.turf + "66" }}>
          <div style={{ ...mono, fontSize: 12, color: T.turf, fontWeight: 700, marginBottom: 4 }}>SUA CONFIRMAÇÃO</div>
          <div style={{ fontSize: 12, color: T.muted, marginBottom: 10 }}>{myPlayer.apelido}, você vai no próximo jogo?</div>
          <div className="flex gap-2">
            {Object.entries(RSVP).map(([k, v]) => {
              const on = jogo.rsvp?.[myPlayer.id]?.s === k;
              return (
                <button key={k} onClick={() => confirmarMinha(k)} disabled={rsvpBusy} className="flex items-center justify-center gap-2" style={{
                  flex: 1, padding: "11px 8px", borderRadius: 10, fontWeight: 700, fontSize: 13, opacity: rsvpBusy ? 0.6 : 1,
                  border: `1px solid ${on ? v.color : T.line}`, background: on ? v.color + "22" : "transparent", color: on ? v.color : T.muted,
                }}><v.Icon size={16} /> {v.label}</button>
              );
            })}
          </div>
          {rsvpErr && <div style={{ color: T.red, fontSize: 12, marginTop: 8 }}>{rsvpErr}</div>}
        </Card>
      )}

      <Card style={{ padding: 16, marginBottom: 16, borderColor: T.amber + "44" }}>
        <div className="flex items-center gap-2 flex-wrap">
          <AlertTriangle size={16} color={T.amber} />
          <span style={{ ...mono, fontSize: 12, color: T.bone, fontWeight: 700 }}>REGRAS DE COBRANÇA</span>
          <div className="flex items-center gap-2" style={{ marginLeft: "auto" }}>
            <span style={{ ...mono, fontSize: 11, color: T.muted }}>Falta R$</span>
            <input type="number" style={{ ...inputStyle, width: 70, padding: "6px 8px" }} value={data.regras.multaFalta} onChange={(e) => setRegra("multaFalta", e.target.value)} />
            <span style={{ ...mono, fontSize: 11, color: T.muted }}>Atraso R$</span>
            <input type="number" style={{ ...inputStyle, width: 70, padding: "6px 8px" }} value={data.regras.multaAtraso} onChange={(e) => setRegra("multaAtraso", e.target.value)} />
          </div>
        </div>
        <div style={{ ...mono, fontSize: 10, color: T.muted, marginTop: 8 }}>Quem marca “Fora” não paga (avisou). Confirmou e não veio = falta. Chegou atrasado = atraso. As multas caem direto no Financeiro.</div>
      </Card>

      <div className="flex items-center justify-between" style={{ marginBottom: 12 }}>
        <SectionTitle Icon={CalendarCheck} color={T.turf}>Confirmações</SectionTitle>
        {isAdmin && <PrimaryBtn onClick={() => setClosing(true)}><ClipboardList size={16} /> Fechar chamada</PrimaryBtn>}
      </div>
      <div className="grid gap-4" style={{ gridTemplateColumns: "repeat(auto-fit,minmax(240px,1fr))" }}>
        {cols.map(([name, color, arr]) => (arr.length > 0 || name === "Confirmados") && (
          <Card key={name} style={{ padding: 14 }}>
            <div className="flex items-center justify-between" style={{ marginBottom: 8 }}>
              <span style={{ ...display, fontSize: 20, color }}>{name}</span>
              <span style={{ ...mono, fontSize: 13, color }}>{arr.length}</span>
            </div>
            {arr.length === 0 && <Empty>ninguém ainda</Empty>}
            {arr.map((p) => (
              <div key={p.id} className="flex items-center gap-2" style={{ padding: "5px 0" }}>
                <Jersey p={p} size={28} />
                <span style={{ flex: 1, fontSize: 13 }}>{p.apelido}</span>
                {isAdmin && <RsvpToggle p={p} />}
              </div>
            ))}
          </Card>
        ))}
      </div>

      {data.chamadas?.length > 0 && (
        <Card style={{ padding: 16, marginTop: 16 }}>
          <SectionTitle Icon={CalendarDays} color={T.muted}>Histórico de chamadas</SectionTitle>
          {data.chamadas.slice(0, 10).map((c) => (
            <div key={c.id || c.data} className="flex items-center justify-between flex-wrap gap-2" style={{ padding: "7px 0", borderBottom: `1px solid ${T.line}44` }}>
              <span style={{ fontSize: 13, textTransform: "capitalize" }}>{new Date(c.data + "T12:00").toLocaleDateString("pt-BR", { weekday: "short", day: "2-digit", month: "2-digit" })}</span>
              <span style={{ ...mono, fontSize: 11 }}>
                <span style={{ color: T.turf }}>{c.vou} vou</span><span style={{ color: T.muted }}> · </span>
                <span style={{ color: T.amber }}>{c.duvida} dúvida</span><span style={{ color: T.muted }}> · </span>
                <span style={{ color: T.red }}>{c.fora} fora</span>
                {c.presentes != null && <span style={{ color: T.muted }}> · {c.presentes} vieram</span>}
              </span>
            </div>
          ))}
        </Card>
      )}

      {closing && <FecharChamada data={data} update={update} onClose={() => setClosing(false)} />}
    </div>
  );
}
function FecharChamada({ data, update, onClose }) {
  const jogo = data.proximoJogo;
  const active = data.players.filter((p) => p.status === "ativo");
  const expected = active.filter((p) => jogo.rsvp[p.id]?.s !== "fora");
  const [marks, setMarks] = useState(() => { const m = {}; expected.forEach((p) => (m[p.id] = "presente")); return m; });
  const set = (id, v) => setMarks((x) => ({ ...x, [id]: v }));
  const preview = expected.reduce((s, p) => s + (marks[p.id] === "falta" ? data.regras.multaFalta : marks[p.id] === "atraso" ? data.regras.multaAtraso : 0), 0);
  const salvar = () => update((d) => {
    const kept = d.multas.filter((m) => m.data !== jogo.data);
    const novas = [];
    expected.forEach((p) => {
      if (marks[p.id] === "falta") novas.push({ id: uid(), playerId: p.id, tipo: "falta", valor: d.regras.multaFalta, data: jogo.data, pago: false });
      if (marks[p.id] === "atraso") novas.push({ id: uid(), playerId: p.id, tipo: "atraso", valor: d.regras.multaAtraso, data: jogo.data, pago: false });
    });
    // Sorteia os que vieram (presente/atraso) → times persistem até o próximo sorteio.
    const vieram = expected.filter((p) => marks[p.id] !== "falta");
    const novoSorteio = vieram.length >= 2
      ? (() => { const [tv, ta] = balanceTeams(vieram); return { data: jogo.data, timeVermelho: tv.players.map((p) => p.id), timeAzul: ta.players.map((p) => p.id) }; })()
      : d.sorteioAtual;
    // Registra a chamada no histórico (acompanhamento jogo a jogo).
    const rsvp = d.proximoJogo.rsvp || {};
    const cont = (s) => active.filter((p) => rsvp[p.id]?.s === s).length;
    const chamada = { id: uid(), data: jogo.data, vou: cont("vou"), duvida: cont("duvida"), fora: cont("fora"), presentes: vieram.length };
    return {
      ...d,
      multas: [...kept, ...novas],
      chamadas: [chamada, ...(d.chamadas || [])],
      sorteioAtual: novoSorteio,
      // Avança para a próxima quinta e reinicia as confirmações.
      proximoJogo: { ...d.proximoJogo, data: nextThursday(), rsvp: {} },
    };
  });
  const opt = [["presente", "Veio", T.turf], ["atraso", "Atrasou", T.amber], ["falta", "Faltou", T.red]];
  return (
    <Modal title="Fechar chamada" onClose={onClose} wide>
      <div style={{ ...mono, fontSize: 11, color: T.muted, marginBottom: 10 }}>
        Marque quem veio. Falta {brl(data.regras.multaFalta)} · atraso {brl(data.regras.multaAtraso)}. Quem marcou “Fora” não entra na lista.
        <br />Ao salvar: lança as multas, <b style={{ color: T.bone }}>sorteia os times de quem veio</b> e já abre a <b style={{ color: T.bone }}>próxima quinta</b> (zerando as confirmações).
      </div>
      <div style={{ maxHeight: 320, overflowY: "auto" }}>
        {expected.map((p) => (
          <div key={p.id} className="flex items-center gap-2" style={{ padding: "6px 0", borderBottom: `1px solid ${T.line}44` }}>
            <Jersey p={p} size={28} />
            <div style={{ flex: 1 }}>
              <span style={{ fontSize: 13 }}>{p.apelido}</span>
              {jogo.rsvp[p.id]?.s && <span style={{ ...mono, fontSize: 9, color: RSVP[jogo.rsvp[p.id].s].color, marginLeft: 6 }}>{RSVP[jogo.rsvp[p.id].s].label.toUpperCase()}</span>}
            </div>
            <div className="flex gap-1">
              {opt.map(([k, lb, c]) => (
                <button key={k} onClick={() => set(p.id, k)} style={{
                  ...mono, fontSize: 10, fontWeight: 700, padding: "5px 8px", borderRadius: 7,
                  color: marks[p.id] === k ? T.bg : c, background: marks[p.id] === k ? c : "transparent", border: `1px solid ${c}`,
                }}>{lb}</button>
              ))}
            </div>
          </div>
        ))}
      </div>
      <div className="flex items-center justify-between" style={{ marginTop: 14 }}>
        <span style={{ ...mono, fontSize: 12, color: T.muted }}>Multas a gerar: <b style={{ color: preview > 0 ? T.amber : T.turf }}>{brl(preview)}</b></span>
      </div>
      <div className="flex gap-2" style={{ marginTop: 12 }}>
        <PrimaryBtn onClick={() => { salvar(); onClose(); }} full>Fechar chamada · sortear e abrir próxima quinta</PrimaryBtn>
        <GhostBtn onClick={onClose}>Cancelar</GhostBtn>
      </div>
    </Modal>
  );
}

/* ============================ FINANCEIRO ============================ */
function Financeiro({ data, update }) {
  const [pix, setPix] = useState(null);
  const months = useMemo(() => {
    const arr = []; const now = new Date();
    for (let i = 2; i >= 0; i--) arr.push(monthKey(new Date(now.getFullYear(), now.getMonth() - i, 1)));
    return arr;
  }, []);
  const mensalistas = data.players.filter((p) => p.mensalista && p.status === "ativo");
  const cur = monthKey();
  const cycle = (id, mk) => update((d) => {
    const order = { undefined: "pago", pago: "pendente", pendente: "atrasado", atrasado: "pago" };
    const c = (d.payments[id] || {})[mk];
    return { ...d, payments: { ...d.payments, [id]: { ...(d.payments[id] || {}), [mk]: order[c] } } };
  });
  const statusColor = { pago: T.turf, pendente: T.amber, atrasado: T.red };
  const addLanc = (l) => update((d) => ({ ...d, lancamentos: [{ ...l, id: uid() }, ...d.lancamentos], club: { ...d.club, caixa: d.club.caixa + (l.tipo === "receita" ? l.valor : -l.valor) } }));
  const delLanc = (l) => { if (!confirm(`Remover "${l.desc}" (${brl(l.valor)})?`)) return; update((d) => ({ ...d, lancamentos: d.lancamentos.filter((x) => x.id !== l.id), club: { ...d.club, caixa: d.club.caixa - (l.tipo === "receita" ? l.valor : -l.valor) } })); };
  const emDia = mensalistas.filter((p) => (data.payments[p.id] || {})[cur] === "pago").length;
  const unpaid = (pid) => data.multas.filter((m) => m.playerId === pid && !m.pago);
  const totalMultas = data.multas.filter((m) => !m.pago).reduce((s, m) => s + m.valor, 0);
  const withMultas = data.players.filter((p) => unpaid(p.id).length > 0);
  const payMulta = (mid) => update((d) => {
    const m = d.multas.find((x) => x.id === mid); if (!m || m.pago) return d;
    return { ...d, multas: d.multas.map((x) => (x.id === mid ? { ...x, pago: true } : x)),
      club: { ...d.club, caixa: d.club.caixa + m.valor },
      lancamentos: [{ id: uid(), data: new Date().toISOString().slice(0, 10), desc: `Multa (${m.tipo}) recebida`, tipo: "receita", valor: m.valor }, ...d.lancamentos] };
  });
  const buildItems = (p) => {
    const items = [];
    const st = (data.payments[p.id] || {})[cur];
    if (p.mensalista && st !== "pago") items.push({ label: `Mensalidade ${monthLabel(cur)}`, valor: data.club.mensalidade });
    unpaid(p.id).forEach((m) => items.push({ label: `Multa · ${m.tipo}`, valor: m.valor }));
    if (items.length === 0) items.push({ label: `Mensalidade ${monthLabel(cur)}`, valor: data.club.mensalidade });
    return items;
  };

  return (
    <div>
      <div className="grid gap-3" style={{ gridTemplateColumns: "repeat(auto-fit,minmax(160px,1fr))", marginBottom: 16 }}>
        <MiniStat label="Caixa atual" value={brl(data.club.caixa)} color={T.turf} />
        <MiniStat label="Mensalidade" value={brl(data.club.mensalidade)} color={T.bone} />
        <MiniStat label={`Em dia (${monthLabel(cur)})`} value={`${emDia}/${mensalistas.length}`} color={T.blue} />
        <MiniStat label="Multas a receber" value={brl(totalMultas)} color={T.amber} />
        <MiniStat label="Inadimplentes" value={mensalistas.filter((p) => (data.payments[p.id] || {})[cur] === "atrasado").length} color={T.red} />
      </div>

      <Card style={{ padding: 16, marginBottom: 16 }}>
        <SectionTitle Icon={Wallet} color={T.turf}>Controle de mensalidades</SectionTitle>
        <div style={{ ...mono, fontSize: 10, color: T.muted, marginBottom: 10 }}>toque no status pra alternar · pago → pendente → atrasado</div>
        <div style={{ overflowX: "auto" }}>
          <div style={{ display: "grid", gridTemplateColumns: `1fr repeat(${months.length},90px) 96px`, gap: 8, minWidth: 480 }}>
            <div />
            {months.map((m) => <div key={m} style={{ ...mono, fontSize: 11, color: T.muted, textAlign: "center", textTransform: "uppercase" }}>{monthLabel(m)}</div>)}
            <div />
            {mensalistas.map((p) => (
              <React.Fragment key={p.id}>
                <div className="flex items-center gap-2" style={{ fontSize: 13 }}><Jersey p={p} size={28} /> {p.apelido}</div>
                {months.map((m) => {
                  const s = (data.payments[p.id] || {})[m];
                  return (
                    <button key={m} onClick={() => cycle(p.id, m)} style={{
                      ...mono, fontSize: 10, fontWeight: 700, textTransform: "uppercase", borderRadius: 8, padding: "7px 0",
                      color: s ? statusColor[s] : T.line, background: s ? statusColor[s] + "1a" : T.bg, border: `1px solid ${s ? statusColor[s] + "55" : T.line}`,
                    }}>{s || "—"}</button>
                  );
                })}
                <button onClick={() => setPix(p)} className="flex items-center justify-center gap-1" style={{ ...mono, fontSize: 10, fontWeight: 700, color: T.gold, border: `1px solid ${T.gold}55`, borderRadius: 8, background: T.gold + "12" }}>
                  <Copy size={11} /> PIX
                </button>
              </React.Fragment>
            ))}
          </div>
        </div>
      </Card>

      <Card style={{ padding: 16, marginBottom: 16, borderColor: T.amber + "44" }}>
        <SectionTitle Icon={AlertTriangle} color={T.amber}>Multas em aberto</SectionTitle>
        {withMultas.length === 0 && <Empty>Ninguém devendo multa. 👏</Empty>}
        {withMultas.map((p) => {
          const ms = unpaid(p.id); const tot = ms.reduce((s, m) => s + m.valor, 0);
          return (
            <div key={p.id} className="flex items-center gap-2 flex-wrap" style={{ padding: "8px 0", borderBottom: `1px solid ${T.line}55` }}>
              <Jersey p={p} size={30} />
              <div style={{ flex: 1, minWidth: 130 }}>
                <div style={{ fontSize: 13 }}>{p.apelido}</div>
                <div style={{ ...mono, fontSize: 10, color: T.muted }}>
                  {ms.map((m) => `${m.tipo} ${new Date(m.data).toLocaleDateString("pt-BR", { day: "2-digit", month: "2-digit" })}`).join(" · ")}
                </div>
              </div>
              <span style={{ ...mono, fontWeight: 700, color: T.amber }}>{brl(tot)}</span>
              <button onClick={() => ms.forEach((m) => payMulta(m.id))} style={smallBtn(T.turf)}><Check size={11} /> Pagar</button>
              <button onClick={() => setPix(p)} style={smallBtn(T.gold)}><Copy size={11} /> PIX</button>
            </div>
          );
        })}
      </Card>

      <div className="grid gap-4" style={{ gridTemplateColumns: "repeat(auto-fit,minmax(300px,1fr))" }}>
        <Card style={{ padding: 16 }}>
          <SectionTitle Icon={ClipboardList} color={T.blue}>Movimentações do caixa</SectionTitle>
          <div className="grid gap-2" style={{ gridTemplateColumns: "1fr 1fr", marginBottom: 12 }}>
            <Field label="Saldo do caixa (R$)">
              <input type="number" style={inputStyle} value={data.club.caixa} onChange={(e) => update((d) => ({ ...d, club: { ...d.club, caixa: +e.target.value } }))} />
            </Field>
            <Field label="Mensalidade (R$)">
              <input type="number" style={inputStyle} value={data.club.mensalidade} onChange={(e) => update((d) => ({ ...d, club: { ...d.club, mensalidade: +e.target.value } }))} />
            </Field>
          </div>
          <LancForm onAdd={addLanc} />
          <div style={{ marginTop: 12 }}>
            {data.lancamentos.slice(0, 8).map((l) => (
              <div key={l.id} className="flex items-center justify-between" style={{ padding: "8px 0", borderBottom: `1px solid ${T.line}55` }}>
                <div>
                  <div style={{ fontSize: 13 }}>{l.desc}</div>
                  <div style={{ ...mono, fontSize: 10, color: T.muted }}>{new Date(l.data).toLocaleDateString("pt-BR")}</div>
                </div>
                <div className="flex items-center gap-2">
                  <span style={{ ...mono, fontWeight: 700, color: l.tipo === "receita" ? T.turf : T.red }}>{l.tipo === "receita" ? "+" : "−"}{brl(l.valor)}</span>
                  <IconBtn onClick={() => delLanc(l)}><Trash2 size={13} color={T.red} /></IconBtn>
                </div>
              </div>
            ))}
          </div>
        </Card>
        <Card style={{ padding: 16 }}>
          <SectionTitle Icon={Wallet} color={T.gold}>Integração bancária</SectionTitle>
          <p style={{ fontSize: 13, color: T.muted, lineHeight: 1.55 }}>
            O botão “PIX” gera um <b style={{ color: T.bone }}>copia-e-cola válido</b> já somando mensalidade + multas de
            falta/atraso do jogador. A baixa automática (marca como pago quando o PIX cai) roda via
            <b style={{ color: T.bone }}> Santander + Open Finance</b> no backend — explicação técnica na conversa.
          </p>
          <Field label="Chave PIX do grupo">
            <input style={inputStyle} value={data.club.pixKey} onChange={(e) => update((d) => ({ ...d, club: { ...d.club, pixKey: e.target.value } }))} />
          </Field>
        </Card>
      </div>

      {pix && <PixModal club={data.club} player={pix} items={buildItems(pix)} onClose={() => setPix(null)} />}
    </div>
  );
}
function LancForm({ onAdd }) {
  const [desc, setDesc] = useState(""); const [valor, setValor] = useState(""); const [tipo, setTipo] = useState("despesa");
  return (
    <div className="flex gap-2 flex-wrap">
      <input placeholder="Descrição (ex: aluguel da quadra)" style={{ ...inputStyle, flex: "2 1 140px" }} value={desc} onChange={(e) => setDesc(e.target.value)} />
      <input type="number" placeholder="R$" style={{ ...inputStyle, flex: "1 1 70px" }} value={valor} onChange={(e) => setValor(e.target.value)} />
      <select style={{ ...inputStyle, flex: "1 1 90px" }} value={tipo} onChange={(e) => setTipo(e.target.value)}>
        <option value="despesa">Despesa</option><option value="receita">Receita</option>
      </select>
      <PrimaryBtn onClick={() => { if (desc && valor) { onAdd({ desc, valor: +valor, tipo, data: new Date().toISOString().slice(0, 10) }); setDesc(""); setValor(""); } }}><Plus size={16} /></PrimaryBtn>
    </div>
  );
}
function PixModal({ club, player, items, onClose }) {
  const [copied, setCopied] = useState(false);
  const [loading, setLoading] = useState(true);
  const [mp, setMp] = useState(null);   // resposta dinâmica do Mercado Pago
  const [mpErr, setMpErr] = useState("");
  const total = items.reduce((s, i) => s + i.valor, 0);
  // PIX estático (fallback): copia-e-cola simples, sem baixa automática
  const staticCode = pixBRCode({ key: club.pixKey, name: club.nome, city: club.cidade, amount: total, txid: "COB" + noAcc(player.apelido).slice(0, 8) });

  // Tenta gerar a cobrança dinâmica no Mercado Pago (com baixa automática).
  useEffect(() => {
    let alive = true;
    (async () => {
      const res = await criarCobrancaPix({ playerId: player.id });
      if (!alive) return;
      if (res.ok && res.qr_code) setMp(res); else setMpErr(res.error || "");
      setLoading(false);
    })();
    return () => { alive = false; };
  }, [player.id]);

  const autobaixa = !!(mp && mp.qr_code);
  const code = autobaixa ? mp.qr_code : staticCode;
  const copy = () => {
    try { navigator.clipboard.writeText(code); } catch { /* fallback: seleção manual */ }
    setCopied(true); setTimeout(() => setCopied(false), 1800);
  };

  return (
    <Modal title={`Cobrança PIX · ${player.apelido}`} onClose={onClose}>
      <div style={{ marginBottom: 12 }}>
        {items.map((i, k) => (
          <div key={k} className="flex items-center justify-between" style={{ padding: "6px 0", borderBottom: `1px solid ${T.line}44` }}>
            <span style={{ fontSize: 13, color: T.muted }}>{i.label}</span>
            <span style={{ ...mono, fontSize: 13, color: T.bone }}>{brl(i.valor)}</span>
          </div>
        ))}
        <div className="flex items-center justify-between" style={{ paddingTop: 10 }}>
          <span style={{ ...display, fontSize: 22, color: T.bone }}>Total</span>
          <span style={{ ...display, fontSize: 36, color: T.turf }}>{brl(total)}</span>
        </div>
      </div>

      {loading ? (
        <div style={{ ...mono, fontSize: 12, color: T.muted, textAlign: "center", padding: 18 }}>Gerando cobrança…</div>
      ) : (
        <>
          {autobaixa && mp.qr_code_base64 && (
            <div style={{ textAlign: "center", marginBottom: 12 }}>
              <img src={`data:image/png;base64,${mp.qr_code_base64}`} alt="QR Code PIX" style={{ width: 176, height: 176, borderRadius: 8, background: "#fff", padding: 6 }} />
            </div>
          )}
          <Field label="PIX copia e cola">
            <textarea readOnly value={code} onFocus={(e) => e.target.select()} style={{ ...inputStyle, height: 90, resize: "none", ...mono, fontSize: 11 }} />
          </Field>
          <PrimaryBtn onClick={copy} full>{copied ? <><Check size={16} /> Copiado!</> : <><Copy size={16} /> Copiar código PIX</>}</PrimaryBtn>
          <div style={{ ...mono, fontSize: 10, marginTop: 10, textAlign: "center", color: autobaixa ? T.turf : T.amber }}>
            {autobaixa
              ? "✓ Baixa automática ativa — marca pago sozinho quando o PIX cair"
              : `Cobrança manual (sem baixa automática)${mpErr ? " · " + mpErr : ""}`}
          </div>
        </>
      )}
    </Modal>
  );
}

/* ============================ PARTIDAS ============================ */
function Partidas({ data, update, stats }) {
  const isAdmin = useIsAdmin();
  const [open, setOpen] = useState(false);
  const byId = (id) => data.players.find((p) => p.id === id);
  const matches = [...data.matches].sort((a, b) => (a.data < b.data ? 1 : -1));
  const del = (m) => { if (confirm("Apagar esta partida?")) update((d) => ({ ...d, matches: d.matches.filter((x) => x.id !== m.id) })); };

  return (
    <div>
      <div className="flex items-center justify-between" style={{ marginBottom: 14 }}>
        <SectionTitle Icon={CalendarDays} color={T.blue}>Partidas · {matches.length}</SectionTitle>
        {isAdmin && <PrimaryBtn onClick={() => setOpen(true)}><Plus size={16} /> Nova partida</PrimaryBtn>}
      </div>
      {matches.length === 0 && <Empty>Nenhuma partida registrada. Bora marcar a próxima quinta.</Empty>}
      <div className="grid gap-3" style={{ gridTemplateColumns: "repeat(auto-fill,minmax(320px,1fr))" }}>
        {matches.map((m) => {
          const golScorers = Object.entries(m.gols || {}).filter(([, n]) => n > 0);
          return (
            <Card key={m.id} style={{ padding: 16 }}>
              <div className="flex items-center justify-between">
                <span style={{ ...mono, fontSize: 11, color: T.muted }}>{new Date(m.data).toLocaleDateString("pt-BR", { weekday: "short", day: "2-digit", month: "2-digit" })}</span>
                <IconBtn onClick={() => del(m)}><Trash2 size={13} color={T.red} /></IconBtn>
              </div>
              <div className="flex items-center justify-center gap-4" style={{ margin: "10px 0" }}>
                <span style={{ ...display, fontSize: 22, color: T.red }}>Time Vermelho</span>
                <span style={{ ...display, fontSize: 40, color: T.bone }}>{m.placarA} <span style={{ color: T.muted }}>×</span> {m.placarB}</span>
                <span style={{ ...display, fontSize: 22, color: T.blue }}>Time Azul</span>
              </div>
              {m.craque && <div style={{ textAlign: "center", ...mono, fontSize: 11, color: T.gold }}><Star size={11} style={{ display: "inline" }} /> Craque: {byId(m.craque)?.apelido}</div>}
              {golScorers.length > 0 && (
                <div style={{ ...mono, fontSize: 11, color: T.muted, marginTop: 8, textAlign: "center" }}>
                  {golScorers.map(([id, n]) => `${byId(id)?.apelido} (${n})`).join(" · ")}
                </div>
              )}
              {(m.equilibrio || m.obs) && (
                <div style={{ marginTop: 10, textAlign: "center" }}>
                  {m.equilibrio && (() => {
                    const c = m.equilibrio === "sim" ? T.turf : m.equilibrio === "nao" ? T.red : T.amber;
                    const txt = m.equilibrio === "sim" ? "✓ Times equilibrados" : m.equilibrio === "nao" ? "✗ Desequilibrados" : "~ Equilíbrio médio";
                    return <span style={{ ...mono, fontSize: 10, fontWeight: 700, padding: "3px 8px", borderRadius: 7, color: c, border: `1px solid ${c}55` }}>{txt}</span>;
                  })()}
                  {m.obs && <div style={{ fontSize: 11, color: T.muted, marginTop: 6, fontStyle: "italic" }}>“{m.obs}”</div>}
                </div>
              )}
            </Card>
          );
        })}
      </div>
      {open && <MatchForm data={data} onClose={() => setOpen(false)} onSave={(m) => { update((d) => ({ ...d, matches: [...d.matches, m] })); setOpen(false); }} />}
    </div>
  );
}
function MatchForm({ data, onClose, onSave }) {
  const active = data.players.filter((p) => p.status === "ativo");
  const [dataJogo, setDataJogo] = useState(data.sorteioAtual?.data || new Date().toISOString().slice(0, 10));
  // Já vem preenchido com o último sorteio (Vermelho = A, Azul = B).
  const [team, setTeam] = useState(() => {
    const sa = data.sorteioAtual; const map = {};
    if (sa?.timeVermelho) { sa.timeVermelho.forEach((id) => (map[id] = "A")); (sa.timeAzul || []).forEach((id) => (map[id] = "B")); }
    return map;
  }); // id -> 'A'|'B'|undefined
  const [placarA, setA] = useState(0); const [placarB, setB] = useState(0);
  const [gols, setGols] = useState({}); const [assist, setAssist] = useState({}); const [craque, setCraque] = useState("");
  const [equilibrio, setEquilibrio] = useState(""); const [obs, setObs] = useState("");

  const present = active.filter((p) => team[p.id]);
  const setT = (id, t) => setTeam((x) => ({ ...x, [id]: x[id] === t ? undefined : t }));
  const autoBalance = () => {
    const sel = active.filter((p) => team[p.id]);
    const pool = sel.length ? sel : active;
    const [a, b] = balanceTeams(pool);
    const map = {}; a.players.forEach((p) => (map[p.id] = "A")); b.players.forEach((p) => (map[p.id] = "B"));
    setTeam(map);
  };
  const save = () => {
    const timeA = present.filter((p) => team[p.id] === "A").map((p) => p.id);
    const timeB = present.filter((p) => team[p.id] === "B").map((p) => p.id);
    onSave({ id: uid(), data: dataJogo, timeA, timeB, placarA: +placarA, placarB: +placarB, gols, assist, craque, equilibrio, obs });
  };

  return (
    <Modal title="Registrar partida" onClose={onClose} wide>
      <div className="flex gap-2 items-end flex-wrap" style={{ marginBottom: 12 }}>
        <Field label="Data"><input type="date" style={inputStyle} value={dataJogo} onChange={(e) => setDataJogo(e.target.value)} /></Field>
        <GhostBtn onClick={autoBalance}><Shuffle size={14} /> Sortear times equilibrados</GhostBtn>
      </div>
      <div style={{ ...mono, fontSize: 11, color: T.muted, marginBottom: 6 }}>
        {data.sorteioAtual?.timeVermelho ? "Times já preenchidos pelo último sorteio — ajuste se precisar:" : "Escolha os presentes e o time (Vermelho/Azul):"}
      </div>
      <div style={{ maxHeight: 220, overflowY: "auto", border: `1px solid ${T.line}`, borderRadius: 10, padding: 8, marginBottom: 12 }}>
        {active.map((p) => (
          <div key={p.id} className="flex items-center gap-2" style={{ padding: "4px 2px" }}>
            <span style={{ flex: 1, fontSize: 13 }}>{p.apelido} <span style={{ ...mono, fontSize: 10, color: T.muted }}>({p.overall})</span></span>
            <button onClick={() => setT(p.id, "A")} title="Time Vermelho" style={teamBtn(team[p.id] === "A", T.red)}>🔴</button>
            <button onClick={() => setT(p.id, "B")} title="Time Azul" style={teamBtn(team[p.id] === "B", T.blue)}>🔵</button>
          </div>
        ))}
      </div>
      <div className="flex items-center justify-center gap-3" style={{ marginBottom: 12 }}>
        <span style={{ ...display, fontSize: 18, color: T.red }}>Vermelho</span>
        <input type="number" style={{ ...inputStyle, width: 64, textAlign: "center", ...mono, fontSize: 20 }} value={placarA} onChange={(e) => setA(e.target.value)} />
        <span style={{ color: T.muted }}>×</span>
        <input type="number" style={{ ...inputStyle, width: 64, textAlign: "center", ...mono, fontSize: 20 }} value={placarB} onChange={(e) => setB(e.target.value)} />
        <span style={{ ...display, fontSize: 18, color: T.blue }}>Azul</span>
      </div>
      {present.length > 0 && (
        <>
          <div style={{ ...mono, fontSize: 11, color: T.muted, marginBottom: 6 }}>Gols e assistências:</div>
          <div style={{ maxHeight: 160, overflowY: "auto", marginBottom: 12 }}>
            {present.map((p) => (
              <div key={p.id} className="flex items-center gap-2" style={{ padding: "5px 0", borderBottom: `1px solid ${T.line}44` }}>
                <span style={{ flex: 1, fontSize: 13, color: team[p.id] === "A" ? T.red : T.blue }}>{p.apelido}</span>
                <span style={{ ...mono, fontSize: 10, color: T.muted }}>G</span>
                <Stepper value={gols[p.id] || 0} onChange={(v) => setGols((x) => ({ ...x, [p.id]: v }))} color={T.red} />
                <span style={{ ...mono, fontSize: 10, color: T.muted }}>A</span>
                <Stepper value={assist[p.id] || 0} onChange={(v) => setAssist((x) => ({ ...x, [p.id]: v }))} color={T.blue} />
              </div>
            ))}
          </div>
          <Field label="Craque da partida (MVP)">
            <select style={inputStyle} value={craque} onChange={(e) => setCraque(e.target.value)}>
              <option value="">— escolher —</option>
              {present.map((p) => <option key={p.id} value={p.id}>{p.apelido}</option>)}
            </select>
          </Field>
        </>
      )}
      <div style={{ ...mono, fontSize: 11, color: T.muted, margin: "4px 0 6px" }}>Avaliação do sorteio:</div>
      <div className="grid gap-3" style={{ gridTemplateColumns: "1fr 1fr", marginBottom: 14 }}>
        <Field label="Os times ficaram parelhos?">
          <select style={inputStyle} value={equilibrio} onChange={(e) => setEquilibrio(e.target.value)}>
            <option value="">— avaliar —</option>
            <option value="sim">✓ Equilibrados</option>
            <option value="mais_ou_menos">~ Mais ou menos</option>
            <option value="nao">✗ Desequilibrados</option>
          </select>
        </Field>
        <Field label="Observação sobre a escolha dos times">
          <input style={inputStyle} placeholder="ex: time Vermelho dominou o meio-campo" value={obs} onChange={(e) => setObs(e.target.value)} />
        </Field>
      </div>
      <PrimaryBtn onClick={save} full>Salvar partida</PrimaryBtn>
    </Modal>
  );
}
const teamBtn = (on, c) => ({ ...mono, fontWeight: 700, width: 30, height: 28, borderRadius: 7, fontSize: 12, color: on ? T.bg : c, background: on ? c : "transparent", border: `1px solid ${c}` });

/* ============================ SORTEAR ============================ */
function Sortear({ data, update }) {
  const admin = useIsAdmin();
  const active = data.players.filter((p) => p.status === "ativo");
  // Presentes já vêm marcados com quem confirmou "Vou"; senão, o último sorteio; senão, os 10 primeiros.
  const confirmados = active.filter((p) => data.proximoJogo?.rsvp?.[p.id]?.s === "vou");
  const sa = data.sorteioAtual;
  const [sel, setSel] = useState(() => {
    let base;
    if (confirmados.length) base = confirmados;
    else if (sa?.timeVermelho) base = [...sa.timeVermelho, ...sa.timeAzul].map((id) => active.find((p) => p.id === id)).filter(Boolean);
    else base = active.slice(0, 10);
    return new Set(base.map((p) => p.id));
  });
  // Times persistem (data.sorteioAtual) até um novo sorteio.
  const [teams, setTeams] = useState(() => {
    if (!sa?.timeVermelho) return null;
    const byId = (id) => data.players.find((p) => p.id === id);
    const mk = (ids) => { const ps = (ids || []).map(byId).filter(Boolean); return { players: ps, total: ps.reduce((s, p) => s + (p.overall || 0), 0) }; };
    return [mk(sa.timeVermelho), mk(sa.timeAzul)];
  });
  const [ciclo, setCiclo] = useState(false); // avisa quando reiniciou o ciclo
  const [pesosVisiveis, setPesosVisiveis] = useState(false); // começa OCULTO (print p/ grupo)
  const selKey = [...sel].sort().join(",");
  const used = new Set(data.sorteioHist?.[selKey] || []);
  // Trocar quem está presente limpa a exibição — mas NÃO no primeiro render (senão apaga o time persistido).
  const firstRender = useRef(true);
  useEffect(() => { if (firstRender.current) { firstRender.current = false; return; } setTeams(null); setCiclo(false); }, [selKey]);
  const toggle = (id) => setSel((s) => { const n = new Set(s); n.has(id) ? n.delete(id) : n.add(id); return n; });
  const run = () => {
    const players = active.filter((p) => sel.has(p.id));
    if (players.length < 2) return;
    const { teams: t, key, exhausted } = balanceTeamsVaried(players, used);
    update((d) => {
      const hist = { ...(d.sorteioHist || {}) };
      hist[selKey] = exhausted ? [key] : [...(hist[selKey] || []), key];
      return { ...d, sorteioHist: hist,
        sorteioAtual: { data: d.proximoJogo?.data, timeVermelho: t[0].players.map((p) => p.id), timeAzul: t[1].players.map((p) => p.id) } };
    });
    setCiclo(exhausted);
    setTeams(t);
  };

  const diff = teams ? Math.abs(teams[0].total - teams[1].total) : 0;
  const maxT = teams ? Math.max(teams[0].total, teams[1].total, 1) : 1;

  return (
    <div>
      <div className="flex items-center justify-between flex-wrap gap-2" style={{ marginBottom: 12 }}>
        <span style={{ ...mono, fontSize: 11, color: T.muted }}>Dica: mantenha os pesos ocultos ao tirar print para o grupo.</span>
        <button onClick={() => setPesosVisiveis((v) => !v)} className="flex items-center gap-2" style={{
          ...mono, fontSize: 11, fontWeight: 700, borderRadius: 8, padding: "6px 12px",
          color: pesosVisiveis ? T.turf : T.muted, border: `1px solid ${pesosVisiveis ? T.turf : T.line}`,
          background: pesosVisiveis ? T.turf + "12" : "transparent",
        }}>
          {pesosVisiveis ? <Eye size={13} /> : <EyeOff size={13} />} {pesosVisiveis ? "pesos visíveis" : "pesos ocultos"}
        </button>
      </div>
      <div className="grid gap-4" style={{ gridTemplateColumns: "minmax(260px,1fr) 2fr" }}>
      <Card style={{ padding: 16 }}>
        <SectionTitle Icon={Users} color={T.turf}>Presentes ({sel.size})</SectionTitle>
        <div style={{ maxHeight: 380, overflowY: "auto" }}>
          {active.map((p) => (
            <button key={p.id} onClick={() => toggle(p.id)} className="flex items-center gap-2 w-full" style={{
              padding: "7px 8px", borderRadius: 9, marginBottom: 4, textAlign: "left",
              background: sel.has(p.id) ? T.panel2 : "transparent", border: `1px solid ${sel.has(p.id) ? T.turf + "55" : T.line}`,
            }}>
              <div style={{ width: 16, height: 16, borderRadius: 5, border: `1px solid ${T.turf}`, background: sel.has(p.id) ? T.turf : "transparent", display: "flex", alignItems: "center", justifyContent: "center" }}>
                {sel.has(p.id) && <Check size={12} color={T.bg} />}
              </div>
              <span style={{ flex: 1, fontSize: 13 }}>{p.apelido}</span>
              <Pill color={POS[p.posicao]}>{p.posicao}</Pill>
              {pesosVisiveis && <span style={{ ...mono, fontSize: 12, color: T.gold, width: 22, textAlign: "right" }}>{p.overall}</span>}
            </button>
          ))}
        </div>
        <PrimaryBtn onClick={run} full><Shuffle size={16} /> {teams ? "Sortear outra vez" : "Equilibrar times"}</PrimaryBtn>
        {used.size > 0 && (
          <div style={{ ...mono, fontSize: 10, color: ciclo ? T.amber : T.muted, textAlign: "center", marginTop: 8 }}>
            {ciclo
              ? "Todas as combinações equilibradas já saíram — recomeçando 🔄"
              : `${used.size} combinação(ões) sorteada(s) · sem repetir`}
          </div>
        )}
      </Card>

      <div>
        {!teams && (
          <Card style={{ padding: 40, textAlign: "center", color: T.muted }}>
            <ArrowLeftRight size={32} color={T.line} style={{ margin: "0 auto 10px" }} />
            Selecione quem veio e clique em <b style={{ color: T.bone }}>Equilibrar times</b>.<br />
            O algoritmo distribui por overall e separa os goleiros.
          </Card>
        )}
        {teams && (
          <>
            <Card style={{ padding: 14, marginBottom: 14 }}>
              <div className="flex items-center justify-between flex-wrap gap-1" style={{ marginBottom: 8, ...mono, fontSize: 11 }}>
                <span style={{ color: T.red, fontWeight: 700 }}>TIME VERMELHO{pesosVisiveis ? `: ${teams[0].total}` : ""}</span>
                <span style={{ color: pesosVisiveis ? (diff <= 3 ? T.turf : diff <= 8 ? T.amber : T.red) : T.turf }}>
                  {pesosVisiveis ? `diferença: ${diff}${diff <= 3 ? " · equilibrado ✓" : ""}` : "times sorteados ✓"}
                </span>
                <span style={{ color: T.blue, fontWeight: 700 }}>TIME AZUL{pesosVisiveis ? `: ${teams[1].total}` : ""}</span>
              </div>
              <div className="flex gap-1" style={{ height: 10 }}>
                <div style={{ flex: teams[0].total, background: T.red, borderRadius: "6px 0 0 6px" }} />
                <div style={{ flex: teams[1].total, background: T.blue, borderRadius: "0 6px 6px 0" }} />
              </div>
            </Card>
            <div className="grid gap-4" style={{ gridTemplateColumns: "1fr 1fr" }}>
              {[["Time Vermelho", T.red, teams[0]], ["Time Azul", T.blue, teams[1]]].map(([name, color, t]) => (
                <Card key={name} style={{ padding: 14, borderColor: color + "55" }}>
                  <div style={{ ...display, fontSize: 24, color, marginBottom: 10 }}>{name}</div>
                  {t.players.map((p) => (
                    <div key={p.id} className="flex items-center gap-2" style={{ padding: "6px 0", borderBottom: `1px solid ${T.line}44` }}>
                      <Jersey p={p} size={30} />
                      <span style={{ flex: 1, fontSize: 13 }}>{p.apelido}</span>
                      {pesosVisiveis && <span style={{ ...mono, fontSize: 13, color }}>{p.overall}</span>}
                    </div>
                  ))}
                </Card>
              ))}
            </div>
          </>
        )}
      </div>
      </div>
    </div>
  );
}

/* ============================ BOTÕES ============================ */
const PrimaryBtn = ({ children, onClick, full }) => (
  <button onClick={onClick} className="flex items-center justify-center gap-2" style={{
    background: T.gold, color: T.bg, fontWeight: 700, fontSize: 13, padding: "9px 16px", borderRadius: 10, width: full ? "100%" : "auto",
  }}>{children}</button>
);
const GhostBtn = ({ children, onClick }) => (
  <button onClick={onClick} className="flex items-center gap-2" style={{
    background: "transparent", color: T.bone, fontWeight: 600, fontSize: 13, padding: "9px 14px", borderRadius: 10, border: `1px solid ${T.line}`,
  }}>{children}</button>
);
const IconBtn = ({ children, onClick, title }) => (
  <button onClick={onClick} title={title} style={{ width: 28, height: 28, borderRadius: 8, border: `1px solid ${T.line}`, background: T.bg, display: "flex", alignItems: "center", justifyContent: "center", color: T.muted }}>{children}</button>
);
const MiniStat = ({ label, value, color }) => (
  <Card style={{ padding: 14 }}>
    <div style={{ ...mono, fontSize: 10, color: T.muted, textTransform: "uppercase" }}>{label}</div>
    <div style={{ ...display, fontSize: 26, color }}>{value}</div>
  </Card>
);
